<template>
  <div class="copy-hover-layer" aria-label="原型协作工具">
    <template v-if="target&&rect"><div class="copy-hover-outline" :style="outlineStyle"/><div class="copy-hover-tools" :style="toolsStyle" @pointerenter="holding=true" @pointerleave="holding=false"><span>{{ label }}</span><button v-if="editable" type="button" :disabled="state.busy" @click.stop="select('edit')">编辑文案</button><button type="button" :disabled="state.busy" @click.stop="select('comments')">备注/评论</button></div></template>
    <button v-if="state.session" class="copy-hover-keyboard" type="button" @click="nextBlock">选择文案区块 <span>↗</span></button>
  </div>
</template>
<script>
import {copyState,registry,canEdit,selectCopyBlock} from '@/copy/operations-copy'
export default {props:{context:{type:Object,required:true}},data:()=>({state:copyState,target:null,rect:null,holding:false}),computed:{id(){return this.target&&this.target.getAttribute('data-copy-block')},label(){return registry.blocks[this.id]?.label||'当前区块'},editable(){return canEdit(this.id)&&registry.blocks[this.id]?.fields.length>0},outlineStyle(){return {left:this.rect.left+'px',top:this.rect.top+'px',width:this.rect.width+'px',height:this.rect.height+'px'}},toolsStyle(){return {left:Math.max(8,Math.min(this.rect.left,window.innerWidth-280))+'px',top:Math.max(8,this.rect.top-34)+'px'}}},watch:{context(){if(!this.holding){this.target=null;this.rect=null}}},mounted(){document.body.appendChild(this.$el);this.onPointer=event=>{if(event.target.closest('.copy-hover-tools'))return;const target=event.target.closest('.review-layout [data-copy-block]');if(!target){clearTimeout(this.hideTimer);this.hideTimer=setTimeout(()=>{if(!this.holding){this.target=null;this.rect=null}},180);return}clearTimeout(this.hideTimer);this.target=target;this.position()};this.onScroll=()=>{if(this.target)this.position()};document.addEventListener('pointermove',this.onPointer);document.addEventListener('focusin',this.onPointer);document.addEventListener('pointerdown',this.onPointer);document.addEventListener('scroll',this.onScroll,true);window.addEventListener('resize',this.onScroll)},beforeDestroy(){clearTimeout(this.hideTimer);document.removeEventListener('pointermove',this.onPointer);document.removeEventListener('focusin',this.onPointer);document.removeEventListener('pointerdown',this.onPointer);document.removeEventListener('scroll',this.onScroll,true);window.removeEventListener('resize',this.onScroll);this.$el.remove()},methods:{position(){if(!this.target?.isConnected){this.rect=null;return}const r=this.target.getBoundingClientRect(),frame=this.target.closest('.phone-frame').getBoundingClientRect(),left=Math.max(r.left,frame.left),right=Math.min(r.right,frame.right),top=Math.max(r.top,frame.top),bottom=Math.min(r.bottom,frame.bottom);this.rect=right>left&&bottom>top?{left,top,width:right-left,height:bottom-top}:null},select(tab){if(this.id)selectCopyBlock(this.id,tab,{...this.context},this.target.hasAttribute('data-copy-fields')?JSON.parse(this.target.getAttribute('data-copy-fields')):undefined)},nextBlock(){const blocks=Array.from(document.querySelectorAll('.review-layout .phone-frame [data-copy-block]')).filter(element=>element.getClientRects().length&&canEdit(element.getAttribute('data-copy-block'))),index=blocks.indexOf(this.target);this.target=blocks[(index+1)%blocks.length];if(this.target){this.target.scrollIntoView({block:'nearest'});this.position();this.holding=true}}}}
</script>
<style>
.copy-hover-layer{font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI","Microsoft Yahei",sans-serif}.copy-hover-outline{position:fixed;pointer-events:none;box-sizing:border-box;border:1.5px solid #d56b60;border-radius:5px;z-index:20000;background:#de685009}.copy-hover-tools{position:fixed;z-index:20001;display:flex;align-items:center;gap:2px;height:30px;padding:2px 4px 2px 9px;box-sizing:border-box;border-radius:6px;background:#fff;border:1px solid #ecd6d2;box-shadow:0 3px 12px #45455718;white-space:nowrap}.copy-hover-tools>span{max-width:90px;overflow:hidden;text-overflow:ellipsis;margin-right:5px;color:#9d8a88;font-size:9px}.copy-hover-tools button{border:0;border-radius:4px;background:#fff7f5;color:#c34d42;padding:3px 7px;font-family:inherit;font-size:11px;line-height:18px;cursor:pointer}.copy-hover-tools button:disabled{opacity:.5;cursor:default}.copy-hover-tools button+button{background:white;color:#737c89}.copy-hover-keyboard{position:fixed;bottom:18px;left:185px;z-index:20001;background:#fff;border:1px solid #e5e8ec;border-radius:7px;box-shadow:0 2px 10px #25283b0c;color:#79828e;padding:8px 11px;font-family:inherit;font-size:10px;line-height:16px;cursor:pointer}.copy-hover-keyboard span{margin-left:8px;color:#bd6d61}.copy-hover-tools button:focus-visible,.copy-hover-keyboard:focus-visible{outline:2px solid #cd665a;outline-offset:2px}@media(max-width:720px){.copy-hover-keyboard{left:12px;bottom:12px}.copy-hover-tools>span{display:none}}
</style>
